// One status grammar for the whole app: shape + word + tint, never colour alone.
// ok = filled dot · bad = filled diamond · pending = spinning ring · unknown = hollow ring
const KIND = { passed: 'ok', failed: 'bad', running: 'pending', queued: 'pending' };

export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

export function mark(kind, text) {
  return `<span class="st st-${kind}"><span class="st-glyph" aria-hidden="true"></span>${esc(text)}</span>`;
}

export const runStatus = (s) => mark(KIND[s] ?? 'unknown', s);

const API = {
  checking: ['pending', 'Checking API'],
  live: ['ok', 'Live'],
  offline: ['unknown', 'API unreachable'],
};

export function renderBadge(api) {
  const [kind, text] = API[api];
  return `<span class="badge" role="status">${mark(kind, text)}</span>`;
}

