import { renderBadge, runStatus, esc } from './components/StatusBadge.js';
import { health, listRuns, retryRun, createRun } from './api/client.js';

// Shown only while the API is unreachable, and labelled as sample data on screen.
const SAMPLE = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const state = { api: 'checking', runs: [], note: '', busy: null };

async function load() {
  try {
    await health();
    state.runs = await listRuns();
    state.api = 'live';
  } catch {
    state.api = 'offline';
    state.runs = SAMPLE;
  }
  render();
}

function row(r) {
  const off = state.api !== 'live' || state.busy ? 'aria-disabled="true" aria-describedby="notice"' : '';
  const busy = state.busy === r.id;
  return `<tr class="${r.status === 'failed' ? 'is-failed' : ''}">
    <th scope="row" class="mono">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td>${runStatus(r.status)}</td>
    <td class="num">${esc(r.started)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="act"><button class="btn retry" data-run="${esc(r.id)}" aria-label="Retry ${esc(r.id)}" ${off}>${busy ? 'Retrying…' : 'Retry'}</button></td>
  </tr>`;
}

function body() {
  if (state.api === 'checking') return `<tr><td colspan="6" class="msg">Loading runs…</td></tr>`;
  if (!state.runs.length) return `<tr><td colspan="6" class="msg">No runs yet. Start one with New run.</td></tr>`;
  return state.runs.map(row).join('');
}

function notice() {
  if (state.note) return state.note;
  if (state.api === 'offline') return 'Showing sample data. The runs API is not responding, so Retry and New run are off until it does.';
  return '';
}

export function render() {
  const failed = state.runs.filter((r) => r.status === 'failed').length;
  const summary = state.api === 'checking' ? '' : `${state.runs.length} runs · ${failed} failed`;
  const off = state.api !== 'live' || state.busy ? 'aria-disabled="true" aria-describedby="notice"' : '';
  const focused = document.activeElement?.dataset?.run ?? document.activeElement?.id;

  document.querySelector('#app').innerHTML = `
    <header class="top">
      <span class="brand">pulse</span>
      ${renderBadge(state.api)}
    </header>
    <main>
      <div class="bar">
        <div>
          <h1>Deploy runs</h1>
          <p class="summary">${summary}</p>
        </div>
        <button id="new-run" class="btn primary" ${off}>${state.busy === 'new' ? 'Starting…' : 'New run'}</button>
      </div>
      <p id="notice" class="notice ${state.api === 'offline' && !state.note ? 'is-sample' : ''}" role="status">${esc(notice())}</p>
      <div class="scroll" role="region" aria-label="Deploy runs" tabindex="0">
        <table>
          <thead><tr>
            <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
            <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
            <th scope="col" class="act"><span class="sr">Actions</span></th>
          </tr></thead>
          <tbody>${body()}</tbody>
        </table>
      </div>
    </main>`;

  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => act(b.dataset.run, `Retry of ${b.dataset.run}`, () => retryRun(b.dataset.run)));
  });
  // ponytail: empty body until the backend ticket defines what a new run needs
  document.querySelector('#new-run').addEventListener('click', () => act('new', 'New run', () => createRun({})));

  if (focused) document.querySelector(`[data-run="${CSS.escape(focused)}"], #${CSS.escape(focused)}`)?.focus();
}

async function act(key, label, call) {
  if (state.api !== 'live' || state.busy) return;
  state.busy = key;
  state.note = '';
  render();
  const res = await call().catch(() => null);
  state.busy = null;
  state.note = res?.ok ? `${label} started.` : `${label} failed: ${res ? `the API returned ${res.status}` : 'the API is unreachable'}.`;
  await load();
}

render();
load();

